int spng_set_srgb(spng_ctx *ctx, uint8_t rendering_intent)
{
    if(ctx == NULL) return 1;

    int ret = get_ancillary2(ctx);
    if(ret) return ret;

    if(rendering_intent > 3) return 1;

    ctx->srgb_rendering_intent = rendering_intent;

    ctx->stored_srgb = 1;
    ctx->user_srgb = 1;

    return 0;
}
